def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        marks = [c for c, value in enumerate(row) if value != 0]
        if len(marks) >= 2:
            for c in range(marks[0] + 1, marks[-1]):
                if row[c] == 0:
                    out[r][c] = 2
    return out
